for tgt_pos, rT, name in [(358, rW, 'Wait@358'), (547, rT, 'Think@547')]:
    h = H[24][tgt_pos]; rms = math.sqrt(float((h**2).mean())+1e-6)
    print('====', name)
    tot=0
    for L in range(24):
        Wp = load(f'model.language_model.layers.{L}.mlp.down_proj.weight').numpy()
